package site.hsu.hub.recruitment.adapter.out.persistence;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="recruitment_stages")public class RecruitmentStageEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="recruitment_id",nullable=false)private Long recruitmentId;@Column(nullable=false,length=30)private String type;@Column(nullable=false,length=100)private String label;@Column(name="starts_at")private Instant startsAt;@Column(name="ends_at")private Instant endsAt;@Column(nullable=false)private boolean enabled;@Column(name="display_order",nullable=false)private int order;protected RecruitmentStageEntity(){}public RecruitmentStageEntity(Long r,String type,String label,Instant start,Instant end,boolean enabled,int order){recruitmentId=r;this.type=type;this.label=label;startsAt=start;endsAt=end;this.enabled=enabled;this.order=order;}public String type(){return type;}public String label(){return label;}public Instant startsAt(){return startsAt;}public Instant endsAt(){return endsAt;}public boolean enabled(){return enabled;}public int order(){return order;}}
